insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_134'
from (values
('127.884.d.1.A',3,'Before using a cutoff saw in a fleet garage, Dev checks the guard and puts on eye and ear protection. He is:','["discussing the safe use of hand and power tools and equipment in transportation systems", "skipping guards", "using the saw bare", "rushing the job"]'::jsonb,0,'Safe tool use.','original'),
('127.884.d.1.A',4,'Inez finds fraying insulation on the cord of a drill in the fleet garage. The safest move is to:','["use it only outdoors", "tag the drill out of service until the cord is repaired", "hand it to a coworker", "wrap the cord in tape and keep drilling"]'::jsonb,1,'Remove damaged tools.','original'),
('127.884.d.1.B',3,'A fleet shop''s manager walks the garage each month with a checklist to find hazards and fix them. This describes:','["avoiding rules", "skipping logs", "using audits and inspections to maintain compliance with safety, health and environmental regulations", "hiding hazards"]'::jsonb,2,'Audits.','original'),
('127.884.d.1.B',4,'An inspection log in a transportation shop is valuable because it:','["hides problems", "replaces training", "adds hazards", "documents when problems were found and fixed"]'::jsonb,3,'Records show compliance.','original'),
('127.884.d.2.A',3,'On a delivery van, a student labels the engine, the brakes, the suspension and the electrical system. She is:','["identifying the major components in a vehicular system", "naming only the paint", "naming only the seats", "naming only the tires"]'::jsonb,0,'Name the systems.','original'),
('127.884.d.2.A',4,'Which of these is a part of a vehicle''s braking system?','["Radiator", "Master cylinder", "Alternator", "Spark plug"]'::jsonb,1,'Brake part.','original'),
('127.884.d.2.B',3,'A fleet mechanic schedules a coolant flush and a belt replacement based on the miles on a bus. He is:','["ignoring service", "waiting for failure", "identifying necessary maintenance and service of vehicular systems", "guessing"]'::jsonb,2,'Scheduled service.','original'),
('127.884.d.2.B',4,'Following the manufacturer''s service interval for oil changes helps:','["hide leaks", "wear out the engine", "raise fuel waste", "protect the engine from wear"]'::jsonb,3,'Interval service.','original'),
('127.884.d.2.C',3,'A fleet adopts a plan that checks tires, fluids and lights on every truck weekly so breakdowns stay low. This is:','["a preventative maintenance plan to keep vehicular systems in good working order", "no plan", "random repairs", "waiting for failure"]'::jsonb,0,'Preventive plan.','original'),
('127.884.d.2.C',4,'Compared with waiting for a breakdown, preventative maintenance usually:','["ignores problems", "lowers downtime and repair cost over time", "raises downtime", "adds breakdowns"]'::jsonb,1,'Prevent costly failures.','original'),
('127.884.d.3.A',3,'A student studies how trucking, rail and shipping move food, fuel and goods that people in a city depend on. She is identifying:','["only paint colors", "no effect", "the scope and effect on society of the energy and power of transportation systems", "only hobby cars"]'::jsonb,2,'Society depends on transportation.','original'),
('127.884.d.3.A',4,'Transportation systems affect society mainly by:','["staying in one place", "using no energy", "moving nothing", "moving people and goods and using large amounts of energy"]'::jsonb,3,'Mobility and energy.','original'),
('127.884.d.3.B',3,'A class debates how electric trucks, hydrogen fuel cells and self-driving freight could change shipping in 20 years. They are:','["identifying potential future scenarios for the energy and power of transportation systems", "ignoring the future", "copying the past", "doing nothing"]'::jsonb,0,'Future scenarios.','original'),
('127.884.d.3.B',4,'A likely effect of more electric delivery vehicles is:','["no change", "fewer tailpipe emissions in cities and more demand for charging", "less electricity use", "more tailpipe soot"]'::jsonb,1,'Electric trend.','original'),
('127.884.d.4.A',3,'A service writer greets a customer, listens to the complaint and then explains the repair plan to the technician in the shop. She is:','["using no words", "avoiding coworkers", "demonstrating communication skills with customers, technicians and other personnel", "ignoring the customer"]'::jsonb,2,'Communication.','original'),
('127.884.d.4.A',4,'The best way to confirm you understood a customer''s complaint is to:','["say nothing", "interrupt", "assume", "restate it in your own words and ask if it''s right"]'::jsonb,3,'Confirm.','original'),
('127.884.d.4.B',3,'A shop clerk prepares a quote for a brake job, then a work order and finally an invoice. She is:','["preparing documentation such as quotes, invoices, bills of lading and work orders", "skipping paperwork", "guessing prices", "ignoring orders"]'::jsonb,0,'Paperwork.','original'),
('127.884.d.4.B',4,'A bill of lading is a document used by:','["pilots only", "carriers to list the goods being shipped and the terms", "chefs only", "students only"]'::jsonb,1,'Shipping document.','original'),
('127.884.d.4.C',3,'A technician reads a lubrication chart and a wiring diagram to service a delivery truck correctly. She is:','["guessing", "ignoring charts", "reading and interpreting documents such as schematics, charts and diagrams", "skipping documents"]'::jsonb,2,'Read documents.','original'),
('127.884.d.4.C',4,'A service chart is useful because it lists:','["owner information", "ticket prices", "parking rules", "fluid types, capacities and intervals for the vehicle"]'::jsonb,3,'Service data.','original'),
('127.884.d.4.D',3,'A technician measures brake rotor thickness with a micrometer and compares it to the minimum in the manual. She is:','["performing precision measurements and using industry specifications to diagnose component wear", "ignoring wear", "eyeballing", "skipping specs"]'::jsonb,0,'Measure vs spec.','original'),
('127.884.d.4.D',4,'If a rotor is thinner than its discard thickness, the technician should:','["paint it", "replace the rotor", "ignore it", "machine it again"]'::jsonb,1,'Below minimum.','original'),
('127.884.d.4.E',3,'A technician hears a noise only when turning right, rules out the engine and tests the wheel bearing until she finds the cause. She is using:','["luck", "guessing", "critical-thinking skills to diagnose vehicular system malfunctions and solve problems", "no process"]'::jsonb,2,'Critical thinking.','original'),
('127.884.d.4.E',4,'The best first step when diagnosing a vehicle problem is to:','["ignore the driver", "guess", "replace parts", "verify the complaint and gather information"]'::jsonb,3,'Start with facts.','original'),
('127.884.d.4.F',3,'A shop learns the rules that govern how vehicles may be built, maintained and operated, such as emission and safety laws. This shows:','["knowledge of regulations that govern the construction, maintenance and operation of vehicles", "ignoring laws", "breaking rules", "avoiding inspections"]'::jsonb,0,'Know the rules.','original'),
('127.884.d.4.F',4,'State vehicle inspection programs exist to:','["raise noise", "keep unsafe or polluting vehicles off the road", "avoid safety", "hide problems"]'::jsonb,1,'Inspection purpose.','original'),
('127.885.d.1.A',3,'A student builds a timeline showing canals, railroads, highways and air cargo as ways the U.S. moved goods over time. She is explaining:','["only cars", "no history", "the history and development of U.S. transportation systems", "only hobbies"]'::jsonb,2,'Transport history.','original'),
('127.885.d.1.A',4,'The transcontinental railroad mattered to U.S. development because it:','["slowed travel", "ended trade", "closed ports", "connected eastern and western markets and speeded travel and freight"]'::jsonb,3,'Railroad impact.','original'),
('127.885.d.1.B',3,'A manager studies how a warehouse, a port and a trucking company coordinate to deliver a shipment on time. She is examining:','["logistics systems used for the transportation of products and services", "only warehouses", "only hobbies", "no systems"]'::jsonb,0,'Logistics.','original'),
('127.885.d.1.B',4,'Logistics is best described as:','["only buying", "planning and managing the flow of goods from source to customer", "only driving", "only selling"]'::jsonb,1,'Flow of goods.','original'),
('127.885.d.1.C',3,'A buyer reads an international contract that says ''FOB'' and ''CIF'' and checks what each term means. She is defining:','["random letters", "slang", "practices and terms commonly used in international sales contracts", "no contract terms"]'::jsonb,2,'Incoterms.','original'),
('127.885.d.1.C',4,'International trade terms published by the International Chamber of Commerce are called:','["Cryptoterms", "Paycodes", "Ticketing", "Incoterms"]'::jsonb,3,'Incoterms.','original'),
('127.885.d.1.D',3,'A student summarizes customs rules, tariffs and trade agreements affecting a shipment from Mexico to Texas. She is:','["summarizing laws and regulations concerning interstate and international trade", "skipping customs", "ignoring laws", "guessing"]'::jsonb,0,'Trade laws.','original'),
('127.885.d.1.D',4,'A broker tells an importer that goods crossing the border will carry a 7 percent duty added at customs. That charge is called a:','["subsidy paid to the buyer", "tariff, a tax on imported goods", "fuel surcharge on the truck", "freight bonus for the driver"]'::jsonb,1,'Tariff.','original'),
('127.885.d.1.E',3,'A class studies how inspections, screening and cargo security at ports help protect trade routes. They are explaining:','["a sales role", "an advertising role", "the role of homeland security in interstate and international trade", "no role"]'::jsonb,2,'Security.','original'),
('127.885.d.1.E',4,'Homeland security programs for cargo are meant to:','["ignore ports", "stop all trade", "add delays only", "keep shipments safe from threats while keeping trade moving"]'::jsonb,3,'Secure cargo.','original'),
('127.885.d.1.F',3,'A planner weighs fuel prices, weather and a labor strike when deciding whether to reroute cargo. She is evaluating:','["risk factors and social and economic trends in transportation", "only color", "no risk", "only paint"]'::jsonb,0,'Evaluate risk.','original'),
('127.885.d.1.F',4,'A rise in fuel prices usually leads carriers to:','["stop operating", "raise rates or look for more efficient routes", "ignore costs", "lower prices always"]'::jsonb,1,'Fuel cost effects.','original'),
('127.885.d.1.G',3,'A shipping coordinator checks that each international container has a commercial invoice, a packing list and customs forms. She is:','["ignoring customs", "skipping forms", "evaluating documentation and other requirements for interstate and international trade", "guessing"]'::jsonb,2,'Documents.','original'),
('127.885.d.1.G',4,'Missing customs paperwork can cause a shipment to be:','["delivered early", "free", "tax exempt", "held or delayed at the border"]'::jsonb,3,'Delay risk.','original'),
('127.885.d.1.H',3,'A dispatcher studies how a late delivery from a supplier can slow a factory''s production line. She is describing:','["transportation issues such as internal processing, product and supply shortages", "no issues", "only parking", "only paint"]'::jsonb,0,'Supply issues.','original'),
('127.885.d.1.H',4,'A product shortage can occur when:','["no one buys", "shipments are delayed or demand rises faster than supply", "goods arrive early", "trucks are idle"]'::jsonb,1,'Shortage.','original'),
('127.885.d.1.I',3,'A new driver arrives on time, follows safety rules, speaks honestly with dispatch and keeps logs accurate. This shows:','["lateness", "dishonesty", "employer expectations, work habits, ethical conduct and legal responsibilities", "ignoring rules"]'::jsonb,2,'Work habits.','original'),
('127.885.d.1.I',4,'Falsifying a driver''s log is:','["acceptable", "helpful", "a shortcut", "unethical and illegal"]'::jsonb,3,'Log fraud.','original'),
('127.885.d.1.J',3,'A dispatcher uses routing software and a spreadsheet to track loads. She is demonstrating:','["computer skills related to transportation and materials handling", "only phone use", "no computer use", "only paper skills"]'::jsonb,0,'Computer skills.','original'),
('127.885.d.1.J',4,'GPS fleet tracking software helps a dispatcher:','["stop trucks", "see where trucks are and adjust routes", "slow trucks", "lose trucks"]'::jsonb,1,'Tracking.','original'),
('127.885.d.2.A',3,'A driver trainee studies hours-of-service limits and inspection requirements set by the U.S. Department of Transportation. She is discussing:','["only city rules", "only company rules", "U.S. Department of Transportation regulations", "no rules"]'::jsonb,2,'DOT.','original'),
('127.885.d.2.A',4,'Hours-of-service rules exist to:','["avoid breaks", "speed trucks", "raise fatigue", "prevent driver fatigue and crashes"]'::jsonb,3,'HOS purpose.','original'),
('127.885.d.2.B',3,'A student explains how DOT, EPA and OSHA each regulate parts of trucking, from emissions to workplace safety. She is explaining:','["the roles of U.S. Department of Transportation, Environmental Protection Agency and OSHA", "no agencies", "only state rules", "one agency only"]'::jsonb,0,'Agency roles.','original'),
('127.885.d.2.B',4,'Which agency primarily regulates workplace safety in a trucking terminal?','["FCC", "OSHA", "IRS", "NASA"]'::jsonb,1,'OSHA.','original'),
('127.885.d.2.C',3,'A warehouse worker puts on safety glasses, gloves and steel-toe boots before unloading pallets. She is examining:','["no equipment", "only tools", "personal protective equipment", "only paint"]'::jsonb,2,'PPE.','original'),
('127.885.d.2.C',4,'Steel-toe boots protect against:','["bright light", "cold drinks", "rain only", "crushing injuries from falling objects"]'::jsonb,3,'Foot protection.','original'),
('127.885.d.2.D',3,'A safety coordinator compares danger signs and caution tags and checks how long the company must keep injury records. She is comparing:','["specifications for accident prevention signs and tags and record retention", "only posters", "only slogans", "no signs"]'::jsonb,0,'Signs and records.','original'),
('127.885.d.2.D',4,'A ''Danger'' sign is used to indicate:','["a food stand", "an immediate hazard", "a fun place", "a tourist spot"]'::jsonb,1,'Danger signage.','original'),
('127.885.d.2.E',3,'A fuel depot manager reviews how to store gasoline, propane and other flammable fuels safely. She is researching:','["only tires", "no requirements", "handling and storage requirements for liquid fuels and liquid petroleum gas", "only paint"]'::jsonb,2,'Fuel storage.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_134'
from (values
('127.885.d.2.E',4,'A yard hand needs to keep ten gallons of gasoline on site for a generator. The correct storage is:','["an open bucket by the shop door", "a bin next to the welder", "a milk jug in the cab", "an approved safety can kept away from sparks and heat"]'::jsonb,3,'Safe storage.','original'),
('127.885.d.2.F',3,'A terminal manager posts exit routes, trains every worker on evacuation steps and runs a drill. She is examining:','["emergency action plans, employee training requirements and evacuation procedures", "no plans", "only rules", "only paperwork"]'::jsonb,0,'Emergency plans.','original'),
('127.885.d.2.F',4,'An evacuation drill is practiced so that employees:','["ignore exits", "know the exits and assembly points before a real emergency", "are surprised", "panic"]'::jsonb,1,'Practice evacuation.','original'),
('127.885.d.2.G',3,'A safety officer reviews the types of portable fire extinguishers and the fire alarm system in a warehouse. She is explaining:','["only drills", "only signs", "fire prevention resources, including portable fire extinguishers and fire alarm systems", "no equipment"]'::jsonb,2,'Fire resources.','original'),
('127.885.d.2.G',4,'A small trash can fire starts in the dock office and Lou grabs an extinguisher. The steps he should follow are:','["plug it in, add water, stir, shake", "pause, act, stay, stop", "push the pin, aim high, stop, spin", "pull the pin, aim at the base, squeeze the handle and sweep side to side"]'::jsonb,3,'PASS method.','original'),
('127.885.d.2.H',3,'A manager writes a fire prevention plan that lists fire hazards, who maintains equipment and how records are kept. She is examining:','["fire prevention plans and documentation", "no plans", "only rumors", "only drills"]'::jsonb,0,'Fire plan.','original'),
('127.885.d.2.H',4,'A written fire prevention plan helps employees know:','["who to blame", "which hazards exist and who is responsible for controlling them", "no hazards", "nothing"]'::jsonb,1,'Plan clarity.','original'),
('127.885.d.3.A',3,'A student driver looks at the dashboard of a tractor and identifies the air pressure gauge, the speedometer and the warning lights. She is:','["skipping lights", "guessing", "reading and interpreting control systems", "ignoring gauges"]'::jsonb,2,'Read gauges.','original'),
('127.885.d.3.A',4,'A low air pressure warning light in a truck cab means:','["drive faster", "turn off the light", "ignore it", "the driver should stop safely and fix the air system"]'::jsonb,3,'Air warning.','original'),
('127.885.d.3.B',3,'Before a trip, a driver checks the tires, brakes, lights and fluid levels and records the results. She is performing:','["vehicle inspections and maintenance such as checking vehicle systems and components", "no checks", "only a wash", "only a radio test"]'::jsonb,0,'Pre-trip.','original'),
('127.885.d.3.B',4,'A pre-trip inspection is done so that:','["no one checks", "defects are found before the vehicle is driven", "defects are hidden", "time is wasted"]'::jsonb,1,'Prevent road failures.','original'),
('127.885.d.3.C',3,'A driver walks around a tractor-trailer, looking at the coupling area, the tires and the lights from front to rear. She is:','["ignoring tires", "skipping the walk", "performing a visual search and inspection of a tractor-trailer", "driving off"]'::jsonb,2,'Walkaround.','original'),
('127.885.d.3.C',4,'When inspecting the fifth wheel coupling, a driver checks that:','["the seat is soft", "the radio works", "the paint is shiny", "the kingpin is locked and no gap is visible"]'::jsonb,3,'Check the lock.','original'),
('127.885.d.3.D',3,'During training, a student practices shifting through gears, backing into a dock and coupling to a trailer. She is demonstrating:','["operation of tractor-trailer controls such as shifting, backing and docking", "only parking", "only steering", "no controls"]'::jsonb,0,'Operate controls.','original'),
('127.885.d.3.D',4,'Before backing a trailer, a driver should:','["honk and go", "get out and look, then use a spotter if possible", "back blindly", "back fast"]'::jsonb,1,'Look first.','original'),
('127.885.d.3.E',3,'A driver leaves extra following distance on a wet road with a heavy load. He is explaining:','["ignoring space", "speeding", "the management and adjustment of vehicle speed and space relations", "tailgating"]'::jsonb,2,'Speed and space.','original'),
('127.885.d.3.E',4,'On wet roads, a loaded truck needs:','["less stopping distance", "the same", "no distance", "more stopping distance than on dry roads"]'::jsonb,3,'Wet roads.','original'),
('127.885.d.3.F',3,'A driver scans ahead and notes that fog, a work zone and a steep downgrade may affect the trip. She is identifying:','["potential driving hazards and environmental conditions", "only sights", "no hazards", "only fun"]'::jsonb,0,'Hazards.','original'),
('127.885.d.3.F',4,'On a long steep downgrade, a heavy truck driver should:','["speed up", "select a lower gear before descending", "coast in neutral", "ride the brakes"]'::jsonb,1,'Gear down.','original'),
('127.885.d.3.G',3,'A driver reviews how to steer around a hazard without losing control and then how to fill out an accident report. She is examining:','["ignoring crashes", "skipping reports", "emergency maneuvers, procedures and accident reports", "hiding accidents"]'::jsonb,2,'Emergency steps.','original'),
('127.885.d.3.G',4,'After an accident, a driver should:','["leave the scene", "hide it", "blame others", "secure the scene, call for help and document the facts"]'::jsonb,3,'After crash.','original'),
('127.885.d.3.H',3,'A trip planner checks the route, fuel stops, weather and delivery window before dispatching a driver. She is discussing:','["appropriate decision-making procedures for planning trips", "no planning", "guessing", "random routes"]'::jsonb,0,'Trip planning.','original'),
('127.885.d.3.H',4,'Planning fuel and rest stops ahead helps a driver:','["ignore breaks", "stay on schedule and within safety limits", "run out of fuel", "drive tired"]'::jsonb,1,'Plan stops.','original'),
('127.885.d.4.A',3,'A new warehouse hire watches a video on OSHA forklift rules, including the need for training and certification. He is explaining:','["optional rules", "no rules", "OSHA forklift safety standards, including operator training and certification", "only guesses"]'::jsonb,2,'Forklift rules.','original'),
('127.885.d.4.A',4,'Under OSHA, a forklift operator must:','["never be trained", "skip evaluation", "be under age 12", "be trained and evaluated before operating the truck"]'::jsonb,3,'Operator training.','original'),
('127.885.d.4.B',3,'Before a shift, an operator checks the forks, tires, horn and floor conditions around a forklift. She is performing:','["a visual inspection of forklifts and their operating environment", "ignoring tires", "skipping checks", "guessing"]'::jsonb,0,'Walk-around.','original'),
('127.885.d.4.B',4,'A forklift with a leaking hydraulic line should be:','["used faster", "tagged out of service until repaired", "left on", "used anyway"]'::jsonb,1,'Tag it out.','original'),
('127.885.d.4.C',3,'An operator buckles up, sounds the horn at intersections and lowers the forks fully when parking. He is discussing:','["random habits", "unsafe habits", "proper start-up, shut-down and traveling procedures", "no procedures"]'::jsonb,2,'Operating procedures.','original'),
('127.885.d.4.C',4,'While traveling with a load, forks should be kept:','["raised high", "pointed forward only", "swinging", "low, just above the floor, and the mast tilted back slightly"]'::jsonb,3,'Travel low.','original'),
('127.885.d.4.D',3,'A fleet manager keeps a daily checklist for every forklift and files it for a year. She is performing:','["maintenance inspections and documentation procedures", "no records", "only guesses", "only pictures"]'::jsonb,0,'Maintenance logs.','original'),
('127.885.d.4.D',4,'Documented forklift inspections help a company:','["avoid checks", "show it keeps equipment safe and find recurring problems", "hide problems", "skip training"]'::jsonb,1,'Records help.','original'),
('127.885.d.4.E',3,'An operator swaps standard forks for a clamp that holds barrels and reviews its capacity plate. He is discussing:','["only fuel", "only paint", "forklift attachments", "no attachments"]'::jsonb,2,'Attachments.','original'),
('127.885.d.4.E',4,'When a forklift uses an attachment, the truck''s rated capacity:','["stays the same", "increases", "is unlimited", "is usually reduced and must be checked on the data plate"]'::jsonb,3,'Capacity changes.','original'),
('127.885.d.4.F',3,'An operator checks that pallets are stable, centered on the forks and stacked in a safe pattern. He is evaluating:','["proper lifting, carrying, load stability and stacking procedures", "guessing weight", "unsafe stacking", "no checks"]'::jsonb,0,'Load stability.','original'),
('127.885.d.4.F',4,'If a load blocks the operator''s view while moving forward, the operator should:','["guess", "travel in reverse with a clear view or use a spotter", "stand up", "go forward faster"]'::jsonb,1,'Maintain view.','original'),
('127.885.d.5.A',3,'A new operator learns to buckle up, check overhead lines and keep bystanders away from the swing of a loader. She is explaining:','["no safety", "only fuel", "safety issues pertaining to heavy equipment operation", "only paint"]'::jsonb,2,'Heavy equipment safety.','original'),
('127.885.d.5.A',4,'Before working near power lines with heavy equipment, an operator should:','["drive under them", "ignore lines", "touch the line", "keep a safe distance and treat every line as energized"]'::jsonb,3,'Overhead hazard.','original'),
('127.885.d.5.B',3,'A mechanic explains how the cooling system, hydraulic pump and tracks on a dozer need regular inspection. She is discussing:','["principles and maintenance of heavy equipment components, including cooling and hydraulic systems", "no maintenance", "only paint", "only decals"]'::jsonb,0,'Component care.','original'),
('127.885.d.5.B',4,'Low hydraulic fluid in heavy equipment can cause:','["no change", "slow or weak operation and pump damage", "less heat", "faster work"]'::jsonb,1,'Hydraulic care.','original'),
('127.885.d.5.C',3,'On a job site, a student watches a dozer push soil, a crawler tractor pull and a front loader move gravel. She is:','["sleeping", "playing", "observing the operation of heavy equipment such as bulldozers, crawler tractors and loaders", "ignoring the site"]'::jsonb,2,'Observe machines.','original'),
('127.885.d.5.C',4,'A bulldozer is mainly used to:','["deliver mail", "wash cars", "carry passengers", "push soil and rock to level or clear land"]'::jsonb,3,'Dozer use.','original'),
('127.885.d.5.D',3,'A hauler explains how to load a track excavator onto a lowboy trailer and secure it with chains. He is discussing:','["the safe transportation of heavy equipment", "unsecured loads", "no safety", "careless hauling"]'::jsonb,0,'Haul safely.','original'),
('127.885.d.5.D',4,'When hauling a heavy machine on a trailer, it must be:','["left loose", "secured with chains or binders rated for the weight", "held by tape", "held by rope"]'::jsonb,1,'Secure the load.','original'),
('127.885.d.5.E',3,'A site foreman removes keys from machines, locks fuel caps and parks equipment inside a fenced yard overnight. She is discussing:','["leaving keys in", "leaving gates open", "equipment theft prevention procedures", "no security"]'::jsonb,2,'Theft prevention.','original'),
('127.885.d.5.E',4,'Recording equipment serial numbers helps a company:','["lose machines", "hide machines", "sell machines", "report and recover stolen machines"]'::jsonb,3,'Serial numbers.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
